package dev.jackteng.encore;
import dev.jackteng.encore.inventory.*;
import dev.jackteng.encore.inventory.StockReturnDiscoveryService.*;
import dev.jackteng.encore.orders.*;
import dev.jackteng.encore.orders.OrderModels.*;
import dev.jackteng.encore.common.ApiErrors.Problem;
import java.util.*;
import java.util.concurrent.*;
import org.junit.jupiter.api.*;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.context.ApplicationContext;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.data.redis.core.StringRedisTemplate;
import org.springframework.transaction.PlatformTransactionManager;
import org.springframework.transaction.support.TransactionTemplate;
import static org.junit.jupiter.api.Assertions.*;
@SpringBootTest(properties={"ticket.delivery.enabled=false","ticket.orders.enabled=true","ticket.purchases.enabled=true","ticket.expiry.enabled=false","ticket.stock-return.enabled=true","ticket.stock-return-recovery.enabled=true","ticket.stock-return-recovery.initial-delay-ms=3600000","ticket.stock-return-discovery.enabled=true","ticket.stock-return-discovery.initial-delay-ms=3600000","ticket.admission.namespace=encore-demo-increment-discovery"})
@TestInstance(TestInstance.Lifecycle.PER_CLASS)
class StockReturnDiscoveryIntegrationTest {
 @Autowired ApplicationContext context;@Autowired JdbcTemplate db;@Autowired StringRedisTemplate redis;
 @Autowired StockReturnDiscoveryService discovery;@Autowired StockReturnDiscoveryWorker scheduler;
 @Autowired StockReturnRecoveryStore recovery;@Autowired StockReturnRecoveryWorker worker;
 @Autowired StockReturnStaffService staff;@Autowired StockProjectionService projection;@Autowired StockSettlementService settlement;
 @Autowired PurchaseService purchases;@Autowired OrderService orders;@Autowired StockHoldService holds;@Autowired PlatformTransactionManager transactions;
 CommitCursorFixture fixtures;String manager="discovery-"+UUID.randomUUID();Set<String> keys=new HashSet<>();
 record Original(CommitCursorFixture.Fixture f,UUID order,Policy policy){}
 @BeforeAll void setup(){fixtures=new CommitCursorFixture(context);db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),manager,"synthetic unused hash","MANAGER");}
 @AfterEach void cleanup()throws Exception{
  for(var row:db.queryForList("SELECT p.request_id,p.version FROM stock_return_discovery_policy p JOIN staff_account a ON a.id=p.actor_id WHERE a.username=? AND p.state<>'STOPPED'",manager))discovery.stop(manager,(UUID)row.get("request_id"),new Stop(UUID.randomUUID(),(Long)row.get("version")));
  long end=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);
  while(db.queryForObject("SELECT count(*) FROM stock_return_recovery_job WHERE state IN ('WAITING','LEASED')",Integer.class)>0){var c=recovery.claim(1);if(c.isPresent())recovery.failed(c.get(),"TEST_CLEANUP",true);else{assertTrue(System.nanoTime()<end);Thread.sleep(100);}}
  redis.delete(keys);keys.clear();
 }
 Original original(boolean extra,int budget,boolean ack){var f=fixtures.accepted(extra);keys.add(fixtures.ledger.key(f.ticket(),1));keys.add(fixtures.ledger.key(f.ticket(),2));keys.add(fixtures.experiment.cursorKey(f.ticket(),1));assertTrue(purchases.process(f.event()));if(ack)assertEquals("COMMITTED",settlement.reconcile(f.intent()).resolution());var order=db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,f.intent());var policy=discovery.enroll(manager,f.ticket(),new Enroll(UUID.randomUUID(),budget));orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));return new Original(f,order,policy);}
 Original original(){return original(false,20,true);}
 UUID discovered(Original o){assertEquals(o.order(),discovery.discoverOne().orElseThrow());var sources=discovery.sources(manager,o.policy().requestId(),1,20);return sources.items().stream().filter(s->s.orderId().equals(o.order())).findFirst().orElseThrow().returnRequestId();}
 void problem(String code,Runnable action){assertEquals(code,assertThrows(Problem.class,action::run).code);}
 int count(String table,UUID request){return db.queryForObject("SELECT count(*) FROM "+table+" WHERE request_id=?",Integer.class,request);}
 @Test void futureDiscoveryAndRecoveryKeepOriginalLedgerAndPublishFreshSnapshot(){var o=original();var before=redis.opsForHash().entries(fixtures.ledger.key(o.f().ticket(),1));var request=discovered(o);assertEquals("REGISTERED",staff.progress(manager,request).state());assertEquals(0,recovery.read(manager,request).attempts());assertTrue(discovery.discoverOne().isEmpty());assertTrue(worker.run(recovery.claim(5).orElseThrow()));assertEquals("DONE",recovery.read(manager,request).state());assertEquals(2,projection.inspect(o.f().ticket()).generation());assertEquals("READY",projection.inspect(o.f().ticket()).state());assertEquals(before,redis.opsForHash().entries(fixtures.ledger.key(o.f().ticket(),1)));assertEquals(1,count("stock_return_ack",request));}
 @Test void alreadyReleasedBeforeEnrollmentIsNotBackfilled(){var o=original();discovery.stop(manager,o.policy().requestId(),new Stop(UUID.randomUUID(),1));assertTrue(discovery.discoverOne().isEmpty());var f=fixtures.accepted(false);keys.add(fixtures.ledger.key(f.ticket(),1));keys.add(fixtures.experiment.cursorKey(f.ticket(),1));assertTrue(purchases.process(f.event()));settlement.reconcile(f.intent());var order=db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,f.intent());orders.cancel(f.owner(),order,new Cancel(UUID.randomUUID(),1));var policy=discovery.enroll(manager,f.ticket(),new Enroll(UUID.randomUUID(),20));assertEquals(3,policy.startRevision());assertTrue(discovery.discoverOne().isEmpty());assertEquals(0,discovery.sources(manager,policy.requestId(),1,20).total());}
 @Test void unacknowledgedCommitIsNotDiscoveredUntilAcknowledged(){var o=original(false,20,false);assertTrue(discovery.discoverOne().isEmpty());assertEquals("COMMITTED",settlement.reconcile(o.f().intent()).resolution());assertNotNull(discovered(o));}
 @Test void originalPolicyBodyReplaysWithFlagsOffAndCannotReplaceBudget(){var o=original();var off=new StockReturnDiscoveryService(db,staff,recovery,false,true,true);assertEquals(o.policy().requestId(),new TransactionTemplate(transactions).execute(tx->off.enroll(manager,o.f().ticket(),new Enroll(o.policy().requestId(),20))).requestId());problem("REQUEST_CONFLICT",()->discovery.enroll(manager,o.f().ticket(),new Enroll(o.policy().requestId(),21)));problem("POLICY_EXISTS",()->discovery.enroll(manager,o.f().ticket(),new Enroll(UUID.randomUUID(),20)));assertTrue(off.discoverOne().isEmpty());}
 @Test void stopIsIrreversibleAndFencesAlreadyEnrolledJob(){var o=original();var request=discovered(o);var body=new Stop(UUID.randomUUID(),1);assertEquals("STOPPED",discovery.stop(manager,o.policy().requestId(),body).state());assertEquals(2,discovery.stop(manager,o.policy().requestId(),body).version());problem("STALE_VERSION",()->discovery.stop(manager,o.policy().requestId(),new Stop(UUID.randomUUID(),1)));assertTrue(worker.run(recovery.claim(5).orElseThrow()));assertEquals("REVIEW",recovery.read(manager,request).state());assertEquals("REGISTERED",staff.progress(manager,request).state());assertEquals(0,count("stock_return_command",request));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_return_discovery_policy SET state='ACTIVE',version=version+1 WHERE request_id=?",o.policy().requestId()));}
 @Test void budgetExhaustionAllowsExistingJobButNoMoreDiscovery(){var o=original(false,1,true);var request=discovered(o);assertEquals("EXHAUSTED",discovery.read(manager,o.policy().requestId()).state());assertEquals(1,discovery.read(manager,o.policy().requestId()).discovered());assertTrue(worker.run(recovery.claim(5).orElseThrow()));assertEquals("DONE",recovery.read(manager,request).state());var body=new Place(UUID.randomUUID(),o.f().ticket(),1,1,1200);var intent=holds.prepare(o.f().owner(),body);assertEquals("HELD",holds.apply(intent.id()).state());var p=purchases.acceptHold(o.f().owner(),intent.id());var event=db.queryForObject("SELECT id FROM purchase_outbox WHERE purchase_id=?",UUID.class,p.id());purchases.process(event);settlement.reconcile(intent.id());var order=db.queryForObject("SELECT order_id FROM stock_hold_decision WHERE intent_id=?",UUID.class,intent.id());orders.cancel(o.f().owner(),order,new Cancel(UUID.randomUUID(),1));assertTrue(discovery.discoverOne().isEmpty());assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_return_discovery_policy SET max_sources=2,version=version+1 WHERE request_id=?",o.policy().requestId()));}
 @Test void existingManualReturnIsRecordedWithoutTakingOver(){var o=original();var request=UUID.randomUUID();assertEquals("APPLIED",staff.submit(manager,o.f().ticket(),o.order(),new StockReturnStaffService.Begin(request,3)).state());assertEquals(o.order(),discovery.discoverOne().orElseThrow());var source=discovery.sources(manager,o.policy().requestId(),1,20).items().getFirst();assertEquals("EXISTING_RETURN",source.disposition());assertNull(source.returnRequestId());assertEquals(0,count("stock_return_recovery_job",request));}
 @Test void concurrentDiscoveryCreatesOneOriginalBodyAndOneRecoveryBudget()throws Exception{var o=original();var start=new CountDownLatch(1);try(var pool=Executors.newFixedThreadPool(4)){var calls=new ArrayList<Future<Optional<UUID>>>();for(int i=0;i<4;i++)calls.add(pool.submit(()->{start.await();return discovery.discoverOne();}));start.countDown();int n=0;for(var f:calls)if(f.get().isPresent())n++;assertEquals(1,n);}assertEquals(1,discovery.sources(manager,o.policy().requestId(),1,20).total());var request=discovery.sources(manager,o.policy().requestId(),1,20).items().getFirst().returnRequestId();assertEquals(1,count("stock_return_staff_audit",request));assertEquals(1,count("stock_return_recovery_audit",request));}
 @Test void sourceInsertFaultRollsBackCommandsJobAndBudget(){var o=original();db.execute("ALTER TABLE stock_return_discovery_source ADD CONSTRAINT discovery_source_fault CHECK(disposition<>'ENROLLED') NOT VALID");try{assertThrows(org.springframework.dao.DataAccessException.class,()->discovery.discoverOne());assertEquals(0,discovery.sources(manager,o.policy().requestId(),1,20).total());assertEquals(0,db.queryForObject("SELECT count(*) FROM stock_return_staff_command WHERE order_id=?",Integer.class,o.order()));}finally{db.execute("ALTER TABLE stock_return_discovery_source DROP CONSTRAINT discovery_source_fault");}assertNotNull(discovered(o));}
 @Test void roleAndOwnershipAreCheckedBeforeDiscoveryAndEveryRecoveryPhase(){var o=original();String other="discovery-other-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),other,"unused synthetic hash","MANAGER");problem("NOT_FOUND",()->discovery.read(other,o.policy().requestId()));db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertEquals("ACTIVE",discovery.read(manager,o.policy().requestId()).state());problem("FORBIDDEN",()->discovery.enroll(manager,o.f().ticket(),new Enroll(UUID.randomUUID(),20)));assertTrue(discovery.discoverOne().isEmpty());}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}var request=discovered(o);db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertTrue(worker.run(recovery.claim(5).orElseThrow()));assertEquals("ACTOR_FORBIDDEN",recovery.read(manager,request).lastCode());assertEquals(0,count("stock_return_ack",request));}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}}
 @Test void changedSourceAndActiveIntentStayFenced(){var o=original(true,20,true);var request=discovered(o);assertTrue(worker.run(recovery.claim(5).orElseThrow()));assertEquals("REVIEW",recovery.read(manager,request).state());assertEquals("BLOCKED",staff.progress(manager,request).state());assertEquals(1,projection.inspect(o.f().ticket()).generation());var later=original();orders.place(later.f().owner(),new Place(UUID.randomUUID(),later.f().ticket(),1,1,1200));var r=discovered(later);assertTrue(worker.run(recovery.claim(5).orElseThrow()));assertEquals("BLOCKED",staff.progress(manager,r).state());assertEquals(0,count("stock_return_ack",r));}
 @Test void immutableHistoryPaginationAndIndependentPhaseGuard(){var o=original();var request=discovered(o);assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("DELETE FROM stock_return_discovery_source WHERE return_request_id=?",request));assertThrows(org.springframework.dao.DataAccessException.class,()->db.update("UPDATE stock_return_discovery_audit SET state=state WHERE policy_id=?",o.policy().requestId()));problem("INVALID_INPUT",()->discovery.sources(manager,o.policy().requestId(),1,21));assertThrows(IllegalStateException.class,()->staff.registerForDiscovery(manager,o.f().ticket(),o.order(),new StockReturnStaffService.Begin(UUID.randomUUID(),3)));assertThrows(IllegalArgumentException.class,()->new StockReturnDiscoveryWorker(discovery,true,21));}
 @Test void ticketLookupIsOwnerOnlyAndReadonlyAfterDowngrade(){var o=original();assertEquals(o.policy().requestId(),discovery.forTicket(manager,o.f().ticket()).requestId());String other="lookup-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),other,"synthetic unused hash","MANAGER");problem("NOT_FOUND",()->discovery.forTicket(other,o.f().ticket()));db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertEquals(o.policy().requestId(),discovery.forTicket(manager,o.f().ticket()).requestId());assertTrue(discovery.settings(manager).enabled());}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}assertEquals(0,discovery.sources(manager,o.policy().requestId(),1,20).total());}
 @Test void stopProofDistinguishesUnknownAndOriginalCommandWithoutWrites(){var o=original();var body=new Stop(UUID.randomUUID(),1);assertEquals("UNKNOWN",discovery.stopProof(manager,o.policy().requestId(),body.requestId(),1).state());assertEquals(0,count("stock_return_discovery_stop",body.requestId()));discovery.stop(manager,o.policy().requestId(),body);var off=new StockReturnDiscoveryService(db,staff,recovery,false,false,false);var proof=new TransactionTemplate(transactions).execute(tx->off.stopProof(manager,o.policy().requestId(),body.requestId(),1));assertEquals("APPLIED",proof.state());assertFalse(proof.policy().enabled());problem("REQUEST_CONFLICT",()->discovery.stopProof(manager,o.policy().requestId(),body.requestId(),2));assertEquals(1,count("stock_return_discovery_stop",body.requestId()));}
 @Test void staleOrDifferentStopProofNeverAdoptsAnotherCommand(){var o=original(false,1,true);discovered(o);var missing=UUID.randomUUID();assertEquals("SUPERSEDED",discovery.stopProof(manager,o.policy().requestId(),missing,1).state());assertEquals(0,count("stock_return_discovery_stop",missing));discovery.stop(manager,o.policy().requestId(),new Stop(UUID.randomUUID(),2));assertEquals("SUPERSEDED",discovery.stopProof(manager,o.policy().requestId(),missing,2).state());db.update("UPDATE staff_account SET role='VIEWER' WHERE username=?",manager);try{assertEquals("SUPERSEDED",discovery.stopProof(manager,o.policy().requestId(),missing,2).state());}finally{db.update("UPDATE staff_account SET role='MANAGER' WHERE username=?",manager);}}
 @Test void enrollmentProofChecksExactImmutableBodyAndConcealsOtherPolicy(){var o=original();var applied=discovery.enrollmentProof(manager,o.f().ticket(),o.policy().requestId(),20);assertEquals("APPLIED",applied.state());assertEquals(o.policy().requestId(),applied.policy().requestId());assertEquals("SUPERSEDED",discovery.enrollmentProof(manager,o.f().ticket(),o.policy().requestId(),21).state());var different=discovery.enrollmentProof(manager,o.f().ticket(),UUID.randomUUID(),20);assertEquals("SUPERSEDED",different.state());assertNull(different.policy());String other="proof-"+UUID.randomUUID();db.update("INSERT INTO staff_account VALUES(?,?,?,?,true)",UUID.randomUUID(),other,"synthetic unused hash","MANAGER");assertNull(discovery.enrollmentProof(other,o.f().ticket(),o.policy().requestId(),20).policy());problem("INVALID_INPUT",()->discovery.enrollmentProof(manager,o.f().ticket(),UUID.randomUUID(),101));}
 @Test void missingEnrollmentProofIsUnknownWithNoPolicyOrBudget(){var f=fixtures.accepted(false);keys.add(fixtures.ledger.key(f.ticket(),1));keys.add(fixtures.experiment.cursorKey(f.ticket(),1));var id=UUID.randomUUID();assertEquals("UNKNOWN",discovery.enrollmentProof(manager,f.ticket(),id,1).state());assertEquals(0,count("stock_return_discovery_policy",id));var off=new StockReturnDiscoveryService(db,staff,recovery,false,false,false);assertFalse(new TransactionTemplate(transactions).execute(tx->off.settings(manager)).enabled());problem("NOT_FOUND",()->discovery.stopProof(manager,UUID.randomUUID(),UUID.randomUUID(),1));}
}
